package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class JsonWriter_value_TriageGen0Test {

    private JsonWriter jsonWriter;
    private StringWriter stringWriter;

    @Before
    public void setUp() throws IOException {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test
    public void testValue_nullValue_callsNullValue() throws IOException {
        doReturn(null).when(jsonWriter).nullValue();
        jsonWriter.value((String) null);
        verify(jsonWriter, times(1)).nullValue();
    }

    @Test
    public void testValue_nonNullValue_callsWriteDeferredName() throws IOException {
        jsonWriter.value("testValue");
        verify(jsonWriter, times(1)).writeDeferredName();
    }

    @Test
    public void testValue_nonNullValue_callsBeforeValueFalse() throws IOException {
        jsonWriter.value("testValue");
        verify(jsonWriter, times(1)).beforeValue(false);
    }

    @Test
    public void testValue_nonNullValue_callsString() throws IOException {
        jsonWriter.value("testValue");
        verify(jsonWriter, times(1)).string("testValue");
    }

    @Test
    public void testValue_nonNullValue_returnsThis() throws IOException {
        JsonWriter result = jsonWriter.value("testValue");
        assertSame(jsonWriter, result);
    }

    @Test(expected = IOException.class)
    public void testValue_throwsIOExceptionIfNullValueThrowsIOException() throws IOException {
        doThrow(IOException.class).when(jsonWriter).nullValue();
        jsonWriter.value((String) null);
    }

    @Test(expected = IOException.class)
    public void testValue_throwsIOExceptionIfWriteDeferredNameThrowsIOException() throws IOException {
        doThrow(IOException.class).when(jsonWriter).writeDeferredName();
        jsonWriter.value("testValue");
    }

    @Test(expected = IOException.class)
    public void testValue_throwsIOExceptionIfBeforeValueFalseThrowsIOException() throws IOException {
        doThrow(IOException.class).when(jsonWriter).beforeValue(false);
        jsonWriter.value("testValue");
    }

    @Test(expected = IOException.class)
    public void testValue_throwsIOExceptionIfStringThrowsIOException() throws IOException {
        doThrow(IOException.class).when(jsonWriter).string("testValue");
        jsonWriter.value("testValue");
    }
}
